/**
 * @distilled.cloud/polymarket-us -- Polymarket US retail API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model that
 * `scripts/convert.ts` converts from Polymarket US's per-area OpenAPI
 * documents (https://docs.polymarket.us/api-reference), merged by the spec
 * mirror. Everything else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import * as PolymarketUs from "@distilled.cloud/polymarket-us";
 *
 * const markets = yield* PolymarketUs.getMarkets({ limit: 10 });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  PolymarketUsProtocol,
  authHeaders,
  isTradingRoute,
  preSignText,
  privateKeyFromSecret,
  type PolymarketUsOpError,
  type PolymarketUsOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
// Operations (and their request/response types) are importable straight off
// the package root. The service-local typed error classes shadow the
// same-named shared ones from ./errors.ts -- the ops raise the service-local
// classes.
export * from "./services/polymarket_us.ts";
export { BadRequest, NotFound } from "./services/polymarket_us.ts";
